#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

typedef pair<int,int> pii;
vector<pii> adj[10000];
int dist[10000];

void dijkstra(int start, int n) {
    fill(dist, dist + n + 1, 1e9);
    dist[start] = 0;
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    pq.push({0, start});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
}

int main() {
    int n, m, s;
    cin >> n >> m >> s;
    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
    }
    dijkstra(s, n);
    for (int i = 1; i <= n; i++) cout << dist[i] << " ";
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int parent[10000];
int find(int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); }

struct Edge { int u, v, w; };
bool cmp(const Edge& a, const Edge& b) { return a.w < b.w; }

int main() {
    int n, m;
    cin >> n >> m;
    Edge edges[100000];
    for (int i = 0; i < m; i++) cin >> edges[i].u >> edges[i].v >> edges[i].w;
    sort(edges, edges + m, cmp);
    for (int i = 1; i <= n; i++) parent[i] = i;
    long long total = 0;
    int cnt = 0;
    for (int i = 0; i < m && cnt < n - 1; i++) {
        int pu = find(edges[i].u), pv = find(edges[i].v);
        if (pu != pv) {
            parent[pu] = pv;
            total += edges[i].w;
            cnt++;
        }
    }
    cout << total << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
using namespace std;

vector<int> adj[10000];
int indegree[10000];

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        indegree[v]++;
    }
    queue<int> q;
    for (int i = 1; i <= n; i++)
        if (indegree[i] == 0) q.push(i);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        cout << u << " ";
        for (int v : adj[u]) {
            indegree[v]--;
            if (indegree[v] == 0) q.push(v);
        }
    }
    return 0;
}
